// src/App.js
import React, { useState } from 'react';
import './App.css';

// --- IMPORT COMPONENT CŨ CỦA NGƯỜI 2 (GIỮ NGUYÊN 100% LOGIC) ---
import BudgetSetting from './components/BudgetSetting';
import DashboardChart from './components/DashboardChart';
import BudgetAlert from './components/BudgetAlert';

// --- IMPORT COMPONENT CỦA NGƯỜI 1 (Nếu chưa có file thì tạm để comment) ---
// import TransactionForm from './components/TransactionForm';
// import TransactionList from './components/TransactionList';

// --- IMPORT TRỌN BỘ COMPONENT TÍNH NĂNG MỚI (ĐỢT 1, 2, 3) ---
import NetWorthSummary from './components/NetWorthSummary';
import CashflowLineChart from './components/CashflowLineChart';
import LoanManager from './components/LoanManager';
import CreditDebtManager from './components/CreditDebtManager';
